import * as THREE from 'three/webgpu';
import { color, float, uniform, mix, vec3 } from 'three/tsl';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'GlassPrismRefraction';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const dispersionAmount = uniform(0.18);

  // Prism geometry: triangular prism, equilateral cross-section 1.2 units per side, length 1.8
  const side = 1.2;
  const length = 1.8;
  const prismShape = new THREE.Shape();
  const h = (Math.sqrt(3) / 2) * side;
  prismShape.moveTo(-side / 2, -h / 3);
  prismShape.lineTo(side / 2, -h / 3);
  prismShape.lineTo(0, (2 * h) / 3);
  prismShape.lineTo(-side / 2, -h / 3);

  const extrudeSettings = { depth: length, bevelEnabled: false, curveSegments: 3 };
  const prismGeo = new THREE.ExtrudeGeometry(prismShape, extrudeSettings);
  prismGeo.translate(0, 0, -length / 2);
  prismGeo.center();

  const prismMaterial = new THREE.MeshPhysicalNodeMaterial({
    color: 0xffffff,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    attenuationColor: new THREE.Color('#e8ecf2'),
    attenuationDistance: 2.5,
    transparent: true,
  });

  // Tint slightly per-channel to fake dispersion via colorNode
  prismMaterial.colorNode = mix(
    color('#ffffff'),
    color('#c9d6ff'),
    dispersionAmount
  );

  const prismMesh = new THREE.Mesh(prismGeo, prismMaterial);
  prismMesh.rotation.z = THREE.MathUtils.degToRad(12);
  prismMesh.rotation.y = THREE.MathUtils.degToRad(20);
  prismMesh.name = 'prismCore';
  group.add(prismMesh);

  // Emissive core: octahedron
  const coreGeo = new THREE.OctahedronGeometry(0.35, 0);
  const coreMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.1,
  });
  const coreMesh = new THREE.Mesh(coreGeo, coreMaterial);
  coreMesh.name = 'emissiveCore';
  group.add(coreMesh);

  // Lights: back rim light (cool, behind-left)
  const rimLight = new THREE.DirectionalLight(new THREE.Color('#9fb0c4'), 3.2);
  rimLight.position.set(-3, 1.2, -2.5);
  rimLight.name = 'rimLight';
  group.add(rimLight);

  const fillLight = new THREE.PointLight(new THREE.Color('#e8ecf2'), 0.8, 6);
  fillLight.position.set(1.5, 1.0, 2.0);
  group.add(fillLight);

  const ambient = new THREE.AmbientLight(new THREE.Color('#16161d'), 0.4);
  group.add(ambient);

  // Caustic streak plane on floor
  const causticGeo = new THREE.PlaneGeometry(2.4, 0.5, 16, 1);
  const causticMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  causticMaterial.colorNode = (function () {
    const uvX = float(0.5); // static gradient approximation via vertex colors below
    return color('#e8ecf2');
  })();

  // Build a gradient via vertex colors for the caustic streak
  const causticPosAttr = causticGeo.attributes.position;
  const colors = new Float32Array(causticPosAttr.count * 3);
  const stops = [
    { at: 0.2, c: new THREE.Color('#ff2a38') },
    { at: 0.5, c: new THREE.Color('#e8ecf2') },
    { at: 0.8, c: new THREE.Color('#9fb0c4') },
  ];
  function sampleGradient(t) {
    if (t <= stops[0].at) return stops[0].c.clone();
    if (t >= stops[stops.length - 1].at) return stops[stops.length - 1].c.clone();
    for (let i = 0; i < stops.length - 1; i++) {
      const a = stops[i], b = stops[i + 1];
      if (t >= a.at && t <= b.at) {
        const f = (t - a.at) / (b.at - a.at);
        return a.c.clone().lerp(b.c, f);
      }
    }
    return stops[0].c.clone();
  }
  for (let i = 0; i < causticPosAttr.count; i++) {
    const x = causticPosAttr.getX(i);
    const t = THREE.MathUtils.clamp((x + 1.2) / 2.4, 0, 1);
    const c = sampleGradient(t);
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  causticGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  causticMaterial.vertexColors = true;
  causticMaterial.colorNode = undefined;

  const causticMesh = new THREE.Mesh(causticGeo, causticMaterial);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0);
  causticMesh.name = 'causticStreak';
  group.add(causticMesh);

  // Text content
  const headlineText = createText(ctx.fontAtlas, {
    text: 'Light, machined.',
    fontSize: 68,
    fontWeight: 600,
    family: 'Lora',
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  headlineText.position.set(0, -1.75, 0);
  headlineText.name = 'headlineText';
  group.add(headlineText);

  const captionText = createText(ctx.fontAtlas, {
    text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
    fontSize: 18,
    fontWeight: 400,
    family: 'JetBrains Mono',
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#9fb0c4',
  });
  captionText.position.set(0, -2.25, 0);
  captionText.name = 'captionText';
  group.add(captionText);

  // Apply cinematic primitives
  const depthRotateHandle = ctx.primitives['depth-rotate'](prismMesh, {
    maxDeg: 10,
    trigger: 'hover',
  });

  // Hover interaction: drive depth-rotate + weighted-settle on release
  let hoverTween = null;
  function onPointerEnter(event) {
    const nx = event?.uv ? event.uv.x * 2 - 1 : 0;
    const ny = event?.uv ? event.uv.y * 2 - 1 : 0;
    if (hoverTween) hoverTween.kill();
    hoverTween = ctx.gsap
      ? ctx.gsap.to(prismMesh.rotation, {
          y: THREE.MathUtils.degToRad(20) + THREE.MathUtils.degToRad(10) * nx,
          x: THREE.MathUtils.degToRad(10) * ny,
          duration: 0.35,
          ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        })
      : null;

    if (causticMesh) {
      causticMesh.scale.x = 1.08;
    }
  }

  function onPointerLeave() {
    if (hoverTween) hoverTween.kill();
    if (ctx.gsap) {
      hoverTween = ctx.gsap.to(prismMesh.rotation, {
        x: 0,
        y: THREE.MathUtils.degToRad(20),
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      });
      ctx.gsap.to(prismMesh.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.05,
        onComplete: () => {
          ctx.gsap.to(prismMesh.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          });
        },
      });
    }
    if (causticMesh) {
      causticMesh.scale.x = 1;
    }
  }

  group.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
  };

  group.userData.cleanup = function cleanup() {
    if (hoverTween) hoverTween.kill();
    if (depthRotateHandle && typeof depthRotateHandle.dispose === 'function') {
      depthRotateHandle.dispose();
    }
    prismGeo.dispose();
    prismMaterial.dispose();
    coreGeo.dispose();
    coreMaterial.dispose();
    causticGeo.dispose();
    causticMaterial.dispose();
    if (headlineText.userData?.cleanup) headlineText.userData.cleanup();
    if (captionText.userData?.cleanup) captionText.userData.cleanup();
    rimLight.dispose?.();
    fillLight.dispose?.();
    ambient.dispose?.();
  };

  return group;
}
